/**
 * Per-function letter context for the English (UK) market. The actual letter
 * body is generated by combining this with the CV example's persona data — so
 * we get realistic letters for every function without hand-writing 20 variants.
 */
interface LetterContext {
  /** Target vacancy title (often slightly different from the candidate's current role) */
  vacancyTitle: string;
  /** Fictional UK company they're applying to */
  recipientCompany: string;
  recipientCity: string;
  /** Optional contact person */
  contactName?: string;
  /** Hooks to weave into the body — concrete to the function */
  hookA: string;
  hookB: string;
  /** Optional availability statement */
  availability?: string;
}

