/**
 * Build a CoverLetterData object from a CV example, using the per-function
 * English letter context. The candidate's name, address, and contact info come
 * from the CV example; the letter body is composed from the hooks plus a
 * generic British-English structure.
 */
export function buildExampleLetter(example: FunctieExample): CoverLetterData {
  const ctx = LETTER_CONTEXTS_EN[example.slug];
  if (!ctx) return createEmptyCoverLetter();

  const now = new Date('2026-05-15').toISOString();
  const greeting = ctx.contactName ? `Dear ${ctx.contactName},` : 'Dear Hiring Manager,';

  const opening = `I am writing to express my strong interest in the ${ctx.vacancyTitle} role at ${ctx.recipientCompany}. The combination of your organisation and this position aligns closely with the direction in which I want to take my career.`;

  const body = `In my current role as ${example.cv.experience[0]?.jobTitle ?? 'professional'}${
    example.cv.experience[0]?.company ? ` at ${example.cv.experience[0].company}` : ''
  }, I have gained experience in ${ctx.hookA}. Alongside that, I actively focus on ${ctx.hookB} — for me that is an essential part of the work. I recognise in the ${ctx.recipientCompany} job advert the way these elements come together.`;

  const closing = `${
    ctx.availability ?? 'I would welcome the opportunity to discuss my application further in person.'
  } You can reach me at ${example.cv.personal.email}${
    example.cv.personal.phone ? ` or on ${example.cv.personal.phone}` : ''
  }.`;

  return {
    id: `example-letter-${example.slug}`,
    createdAt: now,
    updatedAt: now,
    sender: {
      firstName: example.cv.personal.firstName,
      lastName: example.cv.personal.lastName,
      email: example.cv.personal.email,
      phone: example.cv.personal.phone,
      address: example.cv.personal.address || '',
      city: example.cv.personal.city,
      postalCode: example.cv.personal.postalCode || '',
    },
    recipient: {
      contactName: ctx.contactName ?? '',
      contactTitle: '',
      company: ctx.recipientCompany,
      city: ctx.recipientCity,
    },
    vacancyTitle: ctx.vacancyTitle,
    vacancyReference: '',
    date: '2026-05-15',
    letterCity: example.cv.personal.city,
    greeting,
    opening,
    body,
    closing,
    signature: 'Yours sincerely,',
    meta: {
      selectedTemplate: 'modern',
      selectedColorScheme: (example.colorSchemeId as ColorSchemeId) || 'emerald',
    },
  };
}

export function hasLetterContext(slug: string): boolean {
  return slug in LETTER_CONTEXTS_EN;
}

export { LETTER_CONTEXTS_EN };
